((select id from public.lessons where slug = 'understanding-nuance'), 'reading_passage', 'Some outcomes are best understood as emergent: they arise from many interacting factors rather than a single cause, which is why they resist simple prediction.', 5),
((select id from public.lessons where slug = 'at-the-doctors'), 'reading_passage', 'The doctor also recommended the patient rest for two days and drink plenty of water, and to come back if the symptoms did not improve.', 5),
((select id from public.lessons where slug = 'critical-analysis'), 'reading_passage', 'A rigorous critique would ask the report''s authors to isolate confounding variables before asserting that one factor causes another.', 5);
